WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_language_sentence_reorder_bound_sentence'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '捆绑句', 'kp-xingce-language-sentence-reorder-bound-sentence', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "捆绑句"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "找代词！找关联词！强行把两句话绑成死CP。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、找什么？"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "代词捆绑：看到“这”、“其”、“他”。这句话绝对不能排第一，且它前面紧挨着的一句必然有它指代的名词！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "关联词捆绑：看到“不仅”，马上去别的句子里找“而且”；看到“因为”，去找“所以”。这两句必定挨着！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "共同词捆绑：①句结尾有“核聚变”，③句开头有“核聚变”，它们大概率是 ①③ 绑死。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、秒杀选项"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "只要你确定了 ②和⑤ 必须绑在一起（且是 ②⑤ 的顺序），去选项里看，凡是拆散了 ②⑤ 或者写成 ⑤② 的，全部划掉！往往这一步就能杀掉 3 个选项。"}]}]}$$ AS jsonb), NULL, '捆绑句的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "语句表达", "捆绑句"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_sentence_reorder_bound_sentence", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
